<?php
/** Server composition and query boundaries, using real production renderers. */
define('ABSPATH',__DIR__);define('CODELA_THEME_SETTINGS_API_VERSION','1.1.0');
function __( $s,...$args ){return $s;}function esc_html($s){return htmlspecialchars((string)$s,ENT_QUOTES);}function esc_attr($s){return esc_html($s);}function esc_url($s){return esc_html($s);}function esc_html__($s,...$args){return esc_html($s);}function esc_attr_e($s,...$args){echo esc_attr($s);}function sanitize_html_class($s){return $s;}function absint($s){return abs((int)$s);}function get_template_directory_uri(){return '/theme';}
function codela_sf_icon($name){return '<img class="sf-icon" src="/theme/assets/icons/'.$name.'.svg" alt="">';}
function codela_theme_settings(){return $GLOBALS['settings']??[];}function get_bloginfo($s){return 'Store';}function wp_attachment_is_image($id){return in_array($id,[10,11,12],true);}function wp_get_attachment_image($id,$size,$icon,$attrs){return '<img alt="Stone" src="/image-'.$id.'.svg" width="1200" height="900" '.implode(' ',array_map(fn($k,$v)=>$k.'="'.$v.'"',array_keys($attrs),$attrs)).'>';}function wp_get_attachment_image_url($id,$size){return '/image-'.$id.'.svg';}function wp_get_attachment_image_srcset($id,$size){return '/image-'.$id.'.svg 1200w';}function get_term($id,$taxonomy){return $id===7?(object)['term_id'=>7,'name'=>'Lighting']:null;}function get_term_meta(...$a){return 12;}function get_term_link($term,...$args){return '/category/'.(is_object($term)?$term->term_id:$term).'/';}function is_wp_error($s){return false;}function get_option($key){return $key==='woocommerce_hide_out_of_stock_items'?'yes':'';}function wc_get_product_visibility_term_ids(){return ['exclude-from-catalog'=>2,'outofstock'=>3];}function get_post_field(...$a){return '';}function wc_get_page_permalink($s){return '/shop/';}function add_query_arg($k,$v,$url){return $url.'?'.$k.'='.$v;}function codela_sf_product_grid($products){return '<ul class="products">'.implode('',array_map(fn($p)=>'<li class="product"><a href="/product/'.$p->id.'">Product '.$p->id.'</a></li>',$products)).'</ul>';}
class WC_Product{function __construct(public $id){}function is_visible(){return $this->id!==99;}function is_in_stock(){return $this->id!==98;}function get_status(){return 'publish';}}
function wc_get_product($id){return new WC_Product($id);}class WP_Query{public $posts;function __construct($args){$GLOBALS['queries'][]=$args;$this->posts=[1,98,99];}}
require __DIR__.'/../theme/codela-storefront/inc/ui.php';require __DIR__.'/../theme/codela-storefront/inc/homepage.php';
function expect($ok,$msg){if(!$ok)throw new RuntimeException($msg);}
$settings=['homepage_mode'=>'sections','homepage_slides'=>[['enabled'=>true,'image_id'=>10,'mobile_image_id'=>11,'title'=>'Sade yaşam','subtitle'=>'Doğal dokular','button_label'=>'Keşfet','button_url'=>'/shop/'],['enabled'=>true,'image_id'=>12,'title'=>'Işığı keşfet'],['enabled'=>true,'image_id'=>999,'title'=>'Missing']], 'homepage_categories'=>[['term_id'=>7],['term_id'=>99]],'homepage_sections'=>[['enabled'=>true,'title'=>'Yeni ürünler','source'=>'new','category_id'=>7,'limit'=>'4','show_all'=>true],['enabled'=>true,'title'=>'Çok satanlar','source'=>'best_sellers','limit'=>'8','show_all'=>true]]];
$GLOBALS['settings']=$settings;
expect(codela_sf_home_mode()==='sections','Configured mode');$html=codela_sf_home_sections();
expect(substr_count($html,'class="sf-ui-gallery-slide ')===2,'Only valid slides');expect(str_contains($html,'<source media="(max-width:700px)"'),'Responsive mobile image');expect(substr_count($html,'fetchpriority="high"')===1,'Only initial hero receives priority');expect(substr_count($html,'sf-home-category"')===1,'Only existing category');expect(!str_contains($html,'/product/98')&&!str_contains($html,'/product/99'),'Hidden and stock policy');expect(strpos($html,'sf-home-slider')<strpos($html,'sf-home-categories')&&strpos($html,'sf-home-categories')<strpos($html,'sf-home-products'),'Section order');expect(str_contains($html,'/category/7/?orderby=date')&&str_contains($html,'/shop/?orderby=popularity'),'View all preserves query');
expect($GLOBALS['queries'][0]['tax_query'][1]['include_children']===true,'Category descendants');expect($GLOBALS['queries'][1]['meta_key']==='total_sales','Actual Woo sales ordering');expect($GLOBALS['queries'][1]['posts_per_page']===8,'Bounded query');
expect(codela_sf_home_products(['category_id'=>99])===[],'Deleted category does not widen query');
if(getenv('RENDER_HOME')){echo $html;}else{echo "Homepage server rendering, order, visibility, categories and real sales query passed.\n";}
